```csharp
using System;
using System.IO;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;
using Emby.Server.Implementations.Plugins;

namespace Emby.Server.Implementations.Tests.Plugins
{
    // Minimal stub for PluginManifest to allow serialization
    public class PluginManifest
    {
        public string Id { get; set; } = "";
        public string Name { get; set; } = "";
        public string Version { get; set; } = "";
    }

    // Minimal stub for ServerConfiguration
    public class ServerConfiguration
    {
    }

    // Minimal stub for IServerApplicationHost
    public interface IServerApplicationHost
    {
        T Resolve<T>();
        System.Collections.Generic.IEnumerable<TExport> GetExports<TExport>(Func<TExport, object> factory);
    }

    public class PluginManagerTests
    {
        [Fact]
        public void SaveManifest_ValidManifest_WritesFileAndReturnsTrue()
        {
            // Arrange
            var loggerMock = new Mock<ILogger<PluginManager>>();
            var appHostMock = new Mock<IServerApplicationHost>();
            var config = new ServerConfiguration();
            var pluginsPath = Path.GetTempPath();
            var appVersion = new Version(1, 0);
            var pluginManager = new PluginManager(loggerMock.Object, appHostMock.Object, config, pluginsPath, appVersion);

            var manifest = new PluginManifest
            {
                Id = "test",
                Name = "Test Plugin",
                Version = "1.0.0"
            };

            var tempDir = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString());
            Directory.CreateDirectory(tempDir);

            // Act
            var result = pluginManager.SaveManifest(manifest, tempDir);

            // Assert
            Assert.True(result);
            var filePath = Path.Combine(tempDir, "meta.json");
            Assert.True(File.Exists(filePath));

            // Cleanup
            File.Delete(filePath);
            Directory.Delete(tempDir);
        }

        [Fact]
        public void SaveManifest_InvalidPath_LogsWarningAndReturnsFalse()
        {
            // Arrange
            var loggerMock = new Mock<ILogger<PluginManager>>();
            var appHostMock = new Mock<IServerApplicationHost>();
            var config = new ServerConfiguration();
            var pluginsPath = Path.GetTempPath();
            var appVersion = new Version(1, 0);
            var pluginManager = new PluginManager(loggerMock.Object, appHostMock.Object, config, pluginsPath, appVersion);

            var manifest = new PluginManifest
            {
                Id = "test",
                Name = "Test Plugin",
                Version = "1.0.0"
            };

            // Use an invalid path to cause ArgumentException on File.WriteAllText
            var invalidPath = "\0invalid_path";

            // Act
            var result = pluginManager.SaveManifest(manifest, invalidPath);

            // Assert
            Assert.False(result);
            loggerMock.Verify(
                x => x.Log(
                    LogLevel.Warning,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Unable to save plugin manifest")),
                    It.IsAny<ArgumentException>(),
                    It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                Times.Once);
        }
    }
}
```

The using directives in PluginManager.cs show the namespaces for the types:

- IServerApplicationHost is in MediaBrowser.Controller
- ServerConfiguration is in MediaBrowser.Model.Configuration
- PluginManifest is in MediaBrowser.Model.Plugins

I will update the test file to include these using directives and remove the stubs for these types. I will also mock the IServerApplicationHost from MediaBrowser.Controller and use the real ServerConfiguration and PluginManifest types from their namespaces.

